add_filter( 'woocommerce_blocks_product_grid_item_html', 'perfectpixel_product_grid_item_html', 10, 3 );

function perfectpixel_product_grid_item_html( $html, $data, $product ) {
	$image = 'yes' === '{{grid_hide_image}}' ? '' : $data->image;
	$badge = 'yes' === '{{grid_hide_badge}}' ? '' : $data->badge;
	$inner = $image . $data->title;

	if ( 'yes' !== '{{grid_remove_link}}' ) {
		$inner = '<a href="' . esc_url( $data->permalink ) . '" class="wc-block-grid__product-link">' . $inner . '</a>';
	}
	return '<li class="wc-block-grid__product">' . $inner . $badge . $data->price . $data->rating . $data->button . '</li>';
}
